function getTicketMessage(status) {
  switch (status) {
    case 'open': return '접수';
    case 'checking': return '확인 중';
    case 'closed': return '처리 완료';
    default: return '알 수 없음';
  }
}
console.log(getTicketMessage('checking'));

const day = 1;
switch (day) {
  case 1:
    console.log('월요일');
    break;
  case 2:
    console.log('화요일');
    break;
  default:
    console.log('다른 요일');
}

