function getOrderMessage(status) {
  switch (status) {
    case 'paid': return '결제 완료';
    case 'shipping': return '배송 중입니다';
    case 'done': return '배송 완료';
    default: return '상태 확인 중';
  }
}

const method = 'bank';
switch (method) {
  case 'card':
    console.log('카드');
    break;
  case 'bank':
    console.log('계좌이체');
    break;
  default:
    console.log('기타');
}

const command = 'pause';
